import {WORKFLOW_AGENTS,agentState} from './agents.js';
import {TASK_GROUPS} from './tasks.js';
import {validateSchema} from './provider.js';
import {containsSecret,audit,digest} from './security.js';
import {validateCategories} from './editorial.js';
const allowed=['summary','title','article','content','items','titles','headings','tags','categories','posts','themes','gaps'];
const labels={summary:'要点',title:'記事タイトル',article:'本文',content:'内容',items:'確認項目',titles:'タイトル案',headings:'見出し',tags:'タグ',categories:'カテゴリ',posts:'投稿文',themes:'企画の切り口',gaps:'確認したいこと'};
export function editableFields(output){const fields=[];for(const key of allowed){const value=output?.[key];if(typeof value==='string')fields.push({path:[key],label:labels[key],value});else if(Array.isArray(value))value.forEach((item,i)=>{if(typeof item==='string')fields.push({path:[key,i],label:labels[key]+' '+(i+1),value:item});else if(key==='posts'&&typeof item.text==='string')fields.push({path:[key,i,'text'],label:item.platform+'の投稿文',value:item.text});});}return fields;}
export function editedOutput(output,values){const fields=editableFields(output);if(fields.length!==values.length)throw new Error('内容を開き直してください。');const next=structuredClone(output);fields.forEach((f,i)=>{if(typeof values[i]!=='string')throw new Error('文章を入力してください。');let owner=next;for(const key of f.path.slice(0,-1))owner=owner[key];owner[f.path.at(-1)]=values[i];});return next;}
function resetAfter(run,id,includeSelf){const group=TASK_GROUPS.findIndex(g=>g.includes(id));if(group<0)throw new Error('この作業は変更できません。');const ids=[...(includeSelf?[id]:[]),...TASK_GROUPS.slice(group+1).flat()];for(const key of ids){const state=agentState(run,key);Object.assign(state,{status:'queued',output:null,error:'',usage:null,validated:null,annotations:[],durationMs:0});}run.approvals={};run.finalFindings=[];run.reviewFindings=[];run.editorialChecks=[];run.reviewScope='draft';run.rejected=['facts','style','structure','final_check'].reduce((n,key)=>n+(agentState(run,key).validated?.rejected||0),0);run.status='ready';run.error='';run.revision=(run.revision||0)+1;}
export async function saveArtifactEdit(run,id,output){const state=agentState(run,id),agent=WORKFLOW_AGENTS.find(a=>a.id===id);if(!agent||id==='archive'||!state.output||!editableFields(state.output).length)throw new Error('この内容は編集できません。');if(run.status==='running')throw new Error('作業を停止してから編集してください。');validateSchema(output,agent.schema);if(('article' in output&&(!output.article.trim()||!output.title.trim()))||output.posts?.some(p=>!p.text.trim()))throw new Error('タイトル・本文・投稿文を空欄にせず保存してください。');if(JSON.stringify(output).length>100000)throw new Error('文章を短くして保存してください。');if(containsSecret(JSON.stringify(output)))throw new Error('認証情報を含む文章は保存できません。');if(output.categories&&validateCategories(output.categories,run.input.editorialContext?.categoryNames).removed.length)throw new Error('登録されているカテゴリを入力してください。');const fields=editableFields(state.output),proposed=editableFields(output);const reconstructed=editedOutput(state.output,proposed.map(f=>f.value));if(fields.length!==proposed.length||JSON.stringify(reconstructed)!==JSON.stringify(output))throw new Error('文章以外の項目は変更できません。');if(JSON.stringify(output)===JSON.stringify(state.output))return false;state.output=structuredClone(output);resetAfter(run,id,false);await audit(run,'artifact_edited',{agent:id,outputHash:await digest(output),approvalsInvalidated:true});return true;}
export async function prepareRegeneration(run,id){const state=agentState(run,id);if(!state?.output||run.status==='running')throw new Error('作業が完了してから作り直してください。');if(run.attempts>=48||run.status==='budget_exceeded')throw new Error('この制作ではこれ以上作り直せません。成果物を保存してください。');const backup=structuredClone({agents:run.agents,status:run.status,approvals:run.approvals,reviewFindings:run.reviewFindings,finalFindings:run.finalFindings,editorialChecks:run.editorialChecks,rejected:run.rejected,reviewScope:run.reviewScope,revision:run.revision});resetAfter(run,id,true);await audit(run,'artifact_regeneration_requested',{agent:id,approvalsInvalidated:true});return backup;}
export async function restoreRegeneration(run,backup){Object.assign(run,structuredClone(backup));await audit(run,'artifact_regeneration_restored',{reason:'generation_failed',attemptsRetained:true});}
